mapper.select:
SELECT ranked.memberId, ranked.nickname, ranked.profileImage, ranked.followerCount FROM ( SELECT m.id AS memberId, m.nickname AS nickname, m.profile_image AS profileImage, COUNT(f.id) AS followerCount FROM member m LEFT JOIN follow f ON f.following_id = m.id WHERE m.status = 'ACTIVE' GROUP BY m.id, m.nickname, m.profile_image ) ranked
( ranked.followerCount < #{lastFollowerCount} OR ( ranked.followerCount = #{lastFollowerCount} AND ranked.memberId < #{lastMemberId} ) )
ORDER BY ranked.followerCount DESC, ranked.memberId DESC LIMIT #{limit}
